CREATE OR REPLACE FUNCTION public.log_audit_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_record_id INT;
    v_old_val TEXT;
    v_new_val TEXT;
BEGIN
    -- Map the correct IDs and Status columns based on the table being updated
    IF TG_TABLE_NAME = 'customer_accounts' THEN
        v_record_id := NEW.account_id;
        v_old_val := OLD.account_status;
        v_new_val := NEW.account_status;
    ELSIF TG_TABLE_NAME = 'loan_applications' THEN
        v_record_id := NEW.profile_id;
        v_old_val := OLD.approval_status;
        v_new_val := NEW.approval_status;
    END IF;

    -- Only write a log entry if the status actually changed
    IF v_old_val IS DISTINCT FROM v_new_val THEN
        INSERT INTO audit_log (table_name, record_id, action, old_value, new_value, changed_by)
        VALUES (TG_TABLE_NAME, v_record_id, TG_OP, v_old_val, v_new_val, CURRENT_USER);
    END IF;

    RETURN NEW;
END;
-- SECURITY DEFINER is critical here: it allows the trigger to write to the audit_log 
-- even though the Branch Manager doesn't have INSERT permission on this table!
$function$

CREATE OR REPLACE FUNCTION public.auto_create_profile()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM customer_profiles WHERE profile_id = NEW.profile_id) THEN
        INSERT INTO customer_profiles (profile_id, kyc_status) 
        VALUES (NEW.profile_id, 'PENDING');
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.log_balance_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
    IF OLD.balance IS DISTINCT FROM NEW.balance THEN
        INSERT INTO audit_log (account_id, old_balance, new_balance) 
        VALUES (NEW.account_id, OLD.balance, NEW.balance);
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.process_transaction()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    sender_balance NUMERIC(15,2);
    sender_kyc kyc_status_enum;
    receiver_kyc kyc_status_enum;
    sender_status account_status_enum;
    receiver_status account_status_enum;
BEGIN
    -- 1 & 2: Core validaton checks...
    IF NEW.sender_id = NEW.receiver_id THEN RAISE EXCEPTION 'Transaction blocked: Self-transactions are strictly prohibited.'; END IF;
    IF NEW.transaction_type IS NULL THEN RAISE EXCEPTION 'Transaction blocked: A valid transaction type must be selected.'; END IF;

    -- 3 & 4: Look up Sender and Receiver details...
    SELECT ca.balance, cp.kyc_status, ca.account_status INTO sender_balance, sender_kyc, sender_status
    FROM customer_accounts ca JOIN customer_profiles cp ON ca.profile_id = cp.profile_id WHERE ca.account_id = NEW.sender_id;
    SELECT cp.kyc_status, ca.account_status INTO receiver_kyc, receiver_status
    FROM customer_accounts ca JOIN customer_profiles cp ON ca.profile_id = cp.profile_id WHERE ca.account_id = NEW.receiver_id;

    -- 5: Existence Checks...
    IF sender_balance IS NULL THEN RAISE EXCEPTION 'Sender account does not exist.'; END IF;
    IF receiver_kyc IS NULL THEN RAISE EXCEPTION 'Receiver account does not exist.'; END IF;

    -- 6: Operational Status Checks
    IF sender_status IN ('FROZEN', 'CLOSED') THEN RAISE EXCEPTION 'Transaction blocked: Sender account is currently %.', sender_status; END IF;
    IF receiver_status IN ('FROZEN', 'CLOSED') THEN RAISE EXCEPTION 'Transaction blocked: Receiver account is currently %.', receiver_status; END IF;

    -- NEW 6b: Fraud Investigation Check
    IF EXISTS (SELECT 1 FROM fraud_alerts WHERE account_id = NEW.sender_id AND alert_status = 'UNDER_INVESTIGATION') THEN
        RAISE EXCEPTION 'Transaction blocked: Sender account is currently UNDER INVESTIGATION.';
    END IF;
    IF EXISTS (SELECT 1 FROM fraud_alerts WHERE account_id = NEW.receiver_id AND alert_status = 'UNDER_INVESTIGATION') THEN
        RAISE EXCEPTION 'Transaction blocked: Receiver account is currently UNDER INVESTIGATION.';
    END IF;

    -- 7: AML & 8: Financial Checks...
    IF sender_kyc != 'APPROVED' THEN RAISE EXCEPTION 'Transaction blocked: Sender has not completed KYC verification.'; END IF;
    IF receiver_kyc != 'APPROVED' THEN RAISE EXCEPTION 'Transaction blocked: Receiver has not completed KYC verification.'; END IF;
    IF sender_balance < NEW.amount THEN RAISE EXCEPTION 'Insufficient balance for this transaction.'; END IF;

    -- 9. Process Transfer
    UPDATE customer_accounts SET balance = balance - NEW.amount WHERE account_id = NEW.sender_id;
    UPDATE customer_accounts SET balance = balance + NEW.amount WHERE account_id = NEW.receiver_id;

    RETURN NEW;
END;
$function$

