CREATE OR REPLACE FUNCTION public.block_loans_for_closed_accounts()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_kyc_status kyc_status_enum;
BEGIN
    -- 1. Check KYC Status from Customer Profiles
    SELECT kyc_status INTO v_kyc_status 
    FROM customer_profiles 
    WHERE profile_id = NEW.profile_id;

    IF v_kyc_status != 'APPROVED' THEN
        RAISE EXCEPTION 'Loan Application Blocked: Customer KYC must be APPROVED before applying for a loan.';
    END IF;

    -- 2. Check for FROZEN or CLOSED accounts
    IF EXISTS (
        SELECT 1 FROM customer_accounts 
        WHERE profile_id = NEW.profile_id 
          AND account_status IN ('FROZEN', 'CLOSED')
    ) THEN
        RAISE EXCEPTION 'Loan Application Blocked: This customer has a FROZEN or CLOSED account.';
    END IF;

    -- 3. NEW: Prevent Loan Stacking (Block if a loan is already in progress)
    IF EXISTS (
        SELECT 1 FROM loan_applications 
        WHERE profile_id = NEW.profile_id 
          AND approval_status IN ('SUBMITTED', 'UNDERWRITE')
    ) THEN
        RAISE EXCEPTION 'Loan Application Blocked: This customer already has a loan application currently under review.';
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_loan_workflow()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.approval_status IS DISTINCT FROM OLD.approval_status THEN
        -- STATE 1: SUBMITTED -> UNDERWRITE
        IF OLD.approval_status = 'SUBMITTED' THEN
            IF NEW.approval_status != 'UNDERWRITE' THEN 
                RAISE EXCEPTION 'Workflow Error: A SUBMITTED loan must be moved to UNDERWRITE first.'; 
            END IF;
            IF CURRENT_USER != 'senior_underwriter' THEN 
                RAISE EXCEPTION 'Access Denied: Only a Senior Underwriter can move a loan to UNDERWRITE.'; 
            END IF;

        -- STATE 2: UNDERWRITE -> APPROVED or REJECTED
        ELSIF OLD.approval_status = 'UNDERWRITE' THEN
            IF NEW.approval_status NOT IN ('APPROVED', 'REJECTED') THEN 
                RAISE EXCEPTION 'Workflow Error: An UNDERWRITE loan can only be APPROVED or REJECTED.'; 
            END IF;
            IF CURRENT_USER != 'branch_manager' THEN 
                RAISE EXCEPTION 'Access Denied: Only the Branch Manager can APPROVE or REJECT a loan.'; 
            END IF;

            -- Check for FROZEN or CLOSED bank accounts
            IF EXISTS (
                SELECT 1 FROM customer_accounts 
                WHERE profile_id = NEW.profile_id 
                  AND account_status IN ('FROZEN', 'CLOSED')
            ) THEN
                RAISE EXCEPTION 'Workflow Error: Cannot process loan. The customer has a FROZEN or CLOSED account.';
            END IF;

            -- Check for active Fraud Alerts
            IF EXISTS (
                SELECT 1 FROM customer_accounts ca
                JOIN fraud_alerts fa ON ca.account_id = fa.account_id
                WHERE ca.profile_id = NEW.profile_id 
                  AND fa.alert_status IN ('UNDER_INVESTIGATION', 'FROZEN')
            ) THEN
                RAISE EXCEPTION 'Workflow Error: Cannot process loan. A customer account is currently under active Fraud Investigation.';
            END IF;

        -- STATE 3: Terminal States
        ELSIF OLD.approval_status IN ('APPROVED', 'REJECTED') THEN
            RAISE EXCEPTION 'Workflow Error: This loan has already reached a final decision (%).', OLD.approval_status;
        END IF;
    END IF;

    RETURN NEW;
END;
$function$
